sys_ws_operation.operation_script:
(function process(request, response) {
  try {
    var assetTag = request.pathParams['asset_tag'];

    var gr = new GlideRecord('x_848842_techdesk_asset');
    gr.addQuery('asset_tag', assetTag);
    gr.query();

    if (!gr.next()) {
      response.setStatus(404);
      response.setBody({ error: 'Asset not found' });
      return;
    }

    var asset = {
      sys_id: gr.getUniqueValue(),
      asset_tag: gr.getValue('asset_tag'),
      display_name: gr.getValue('display_name'),
      asset_type: gr.getValue('asset_type'),
      lifecycle_state: gr.getValue('lifecycle_state'),
      serial_number: gr.getValue('serial_number'),
      assigned_to: gr.getDisplayValue('assigned_to'),
      location: gr.getDisplayValue('location'),
      purchase_date: gr.getValue('purchase_date'),
      warranty_expiry: gr.getValue('warranty_expiry'),
      last_audit_date: gr.getValue('last_audit_date'),
      sys_created_on: gr.getValue('sys_created_on'),
      sys_updated_on: gr.getValue('sys_updated_on')
    };

    response.setStatus(200);
    response.setBody(asset);
  } catch (e) {
    gs.error('TechDesk CMDB Get Asset error: ' + e.message);
    response.setStatus(500);
    response.setBody({ error: 'Internal server error', message: e.message });
  }
})(request, response);
